import axios from"axios";const apiClient=axios.create({baseURL:"https://api-os.bogdanauto.com.ua/api/v1",headers:{"Content-Type":"application/json"}});apiClient.interceptors.request.use(e=>{var o=localStorage.getItem("token");return o&&(e.headers.Authorization="Bearer "+o),e}),apiClient.interceptors.response.use(e=>e,e=>(401===e.response?.status&&(localStorage.removeItem("token"),localStorage.removeItem("organizationSlug"),window.location.href="/login"),Promise.reject(e)));export{apiClient};